import memfs from 'memfs'
import { path, FileSystem } from '@servicenow/sdk-build-core'
import type { FileSystem as IFileSystem } from '@servicenow/sdk-build-core'
import { Project } from '../../src'
import { projectHasScript, runScriptInProject } from '../../src/util/script-runner'

// Mock environment to force using require() instead of dynamic import()
// This avoids Jest's module resolution issues
jest.mock('../../src/util/environment', () => ({
    isWebWorker: true,
    hasModuleLoader: () => true,
}))

describe('script-runner tests', () => {
    let vol: memfs.Volume
    let fs: IFileSystem
    let project: Project

    beforeEach(() => {
        vol = new memfs.Volume()
        fs = memfs.createFsFromVolume(vol) as FileSystem
    })

    describe('projectHasScript', () => {
        test('returns false when no script exists (not in config, no fallback)', () => {
            project = new Project({
                rootDir: '/',
                fileSystem: fs,
                config: { scope: 'x_test', scopeId: '12345' },
            })

            expect(projectHasScript(project, 'nonexistent')).toBe(false)
        })

        test('returns false when config script file does not exist', () => {
            project = new Project({
                rootDir: '/',
                fileSystem: fs,
                config: {
                    scope: 'x_test',
                    scopeId: '12345',
                    scripts: { myScript: 'scripts/my-script.js' },
                },
            })

            expect(projectHasScript(project, 'myScript')).toBe(false)
        })

        test('returns true when config script exists', () => {
            vol.fromNestedJSON({
                '/scripts': { 'my-script.js': 'console.log("hello")' },
            })

            project = new Project({
                rootDir: '/',
                fileSystem: fs,
                config: {
                    scope: 'x_test',
                    scopeId: '12345',
                    scripts: { myScript: 'scripts/my-script.js' },
                },
            })

            expect(projectHasScript(project, 'myScript')).toBe(true)
        })

        test('returns true when fallback now.scriptName.mjs exists', () => {
            vol.fromNestedJSON({
                '/': { 'now.prebuild.mjs': 'export default function() {}' },
            })

            project = new Project({
                rootDir: '/',
                fileSystem: fs,
                config: { scope: 'x_test', scopeId: '12345' },
            })

            expect(projectHasScript(project, 'prebuild')).toBe(true)
        })

        describe('script path resolution', () => {
            test('handles relative paths', () => {
                vol.fromNestedJSON({
                    '/my-scripts': { 'helper.js': 'module.exports.default = function() {}' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { helper: 'my-scripts/helper.js' },
                    },
                })

                expect(projectHasScript(project, 'helper')).toBe(true)
            })

            test('handles absolute paths', () => {
                const absolutePath = path.resolve('/', 'absolute/script.js')
                vol.fromNestedJSON({
                    '/absolute': { 'script.js': 'module.exports.default = function() {}' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { absolute: absolutePath },
                    },
                })

                expect(projectHasScript(project, 'absolute')).toBe(true)
            })

            test('is case-sensitive', () => {
                vol.fromNestedJSON({
                    '/scripts': { 'MyScript.js': 'module.exports.default = function() {}' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { MyScript: 'scripts/MyScript.js' },
                    },
                })

                expect(projectHasScript(project, 'MyScript')).toBe(true)
                expect(projectHasScript(project, 'myscript')).toBe(false)
            })
        })
    })

    describe('runScriptInProject', () => {
        let consoleInfoSpy: jest.SpyInstance
        let consoleWarnSpy: jest.SpyInstance

        beforeEach(() => {
            consoleInfoSpy = jest.spyOn(console, 'info').mockImplementation()
            consoleWarnSpy = jest.spyOn(console, 'warn').mockImplementation()
        })

        afterEach(() => {
            consoleInfoSpy.mockRestore()
            consoleWarnSpy.mockRestore()
        })

        describe('when script not found', () => {
            test('returns silently when throwIfNotFound is false', async () => {
                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: { scope: 'x_test', scopeId: '12345' },
                })

                await expect(
                    runScriptInProject({
                        scriptName: 'nonexistent',
                        project,
                        throwIfNotFound: false,
                    })
                ).resolves.toBeUndefined()
            })

            test('throws with helpful message when throwIfNotFound is true', async () => {
                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: { scope: 'x_test', scopeId: '12345' },
                })

                await expect(
                    runScriptInProject({
                        scriptName: 'missing',
                        project,
                        throwIfNotFound: true,
                    })
                ).rejects.toThrow(
                    'No script defined for "missing". Please add it to scripts in now.config.json or create now.missing.mjs.'
                )
            })
        })

        describe('when config script exists', () => {
            test('verifies script is found and ready for execution', () => {
                vol.fromNestedJSON({
                    '/scripts': { 'test-script.js': 'export default function() {}' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { testScript: 'scripts/test-script.js' },
                    },
                })

                // Script exists and passes all pre-execution checks
                expect(projectHasScript(project, 'testScript')).toBe(true)

                // Verify path resolution works correctly
                const resolvedPath = project.resolvePath('scripts/test-script.js')
                expect(resolvedPath).toContain('test-script.js')
            })

            test('validates script file exists before execution attempt', () => {
                vol.fromNestedJSON({
                    '/scripts': { 'build-script.js': 'export default function() { return "executed"; }' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { build: 'scripts/build-script.js' },
                    },
                })

                // Pre-execution validation passes
                expect(projectHasScript(project, 'build')).toBe(true)

                // File exists on filesystem
                const scriptFs = project.getFileSystem()
                const scriptPath = project.resolvePath('scripts/build-script.js')
                expect(FileSystem.existsSync(scriptFs, scriptPath)).toBe(true)
            })
        })

        describe('when fallback script exists', () => {
            test('finds and attempts to run fallback', () => {
                vol.fromNestedJSON({
                    '/': { 'now.postbuild.mjs': 'export default function() { console.log("deployed"); }' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: { scope: 'x_test', scopeId: '12345' },
                })

                // Fallback exists and should be found
                expect(projectHasScript(project, 'postbuild')).toBe(true)
            })

            test('ignores fallback when config script defined but missing', async () => {
                vol.fromNestedJSON({
                    '/': { 'now.broken.mjs': 'export default function() {}' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { broken: 'scripts/does-not-exist.js' },
                    },
                })

                await expect(
                    runScriptInProject({
                        scriptName: 'broken',
                        project,
                        throwIfNotFound: true,
                    })
                ).rejects.toThrow('Script "broken" defined in config at "scripts/does-not-exist.js" not found')
            })
        })

        describe('error messages', () => {
            test('includes config path when defined script not found', async () => {
                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { broken: 'scripts/does-not-exist.js' },
                    },
                })

                await expect(
                    runScriptInProject({
                        scriptName: 'broken',
                        project,
                        throwIfNotFound: true,
                    })
                ).rejects.toThrow(/scripts\/does-not-exist\.js/)
            })

            test('suggests both options when script not configured', async () => {
                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: { scope: 'x_test', scopeId: '12345' },
                })

                await expect(
                    runScriptInProject({
                        scriptName: 'missing',
                        project,
                        throwIfNotFound: true,
                    })
                ).rejects.toThrow(/now\.missing\.mjs/)
            })
        })

        describe('script execution', () => {
            function registerMockScript(scriptPath: string, moduleExports: any) {
                // Use jest.doMock to register the module
                jest.doMock(scriptPath, () => moduleExports, { virtual: true })
            }

            test('executes a single function task successfully', async () => {
                // Create script file in memfs
                vol.fromNestedJSON({
                    '/scripts': { 'test-script.js': '' }, // File must exist for projectHasScript
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { testScript: 'scripts/test-script.js' },
                    },
                })

                // Register the module that require() will return
                const scriptPath = project.resolvePath('scripts/test-script.js')
                registerMockScript(scriptPath, {
                    default: (context: any) => {
                        context.fs.writeFileSync(context.path.join(context.rootDir, 'marker.txt'), 'executed')
                    },
                })

                // Call the REAL runScriptInProject
                await runScriptInProject({
                    scriptName: 'testScript',
                    project,
                })

                // Verify the script actually executed
                const markerPath = path.join('/', 'marker.txt')
                expect(FileSystem.existsSync(fs, markerPath)).toBe(true)
                const content = fs.readFileSync(markerPath, { encoding: 'utf-8' })
                expect(content).toBe('executed')

                // Verify logger messages
                expect(consoleInfoSpy).toHaveBeenCalledWith(expect.stringContaining('Running script "testScript"'))
                expect(consoleInfoSpy).toHaveBeenCalledWith(
                    expect.stringContaining('Script "testScript" completed successfully')
                )
            })

            test('executes multiple function tasks in array', async () => {
                vol.fromNestedJSON({
                    '/scripts': { 'multi-task.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { multiTask: 'scripts/multi-task.js' },
                    },
                })

                const scriptPath = project.resolvePath('scripts/multi-task.js')
                registerMockScript(scriptPath, {
                    default: [
                        (context: any) => {
                            context.fs.appendFileSync(context.path.join(context.rootDir, 'log.txt'), 'task1\n')
                        },
                        (context: any) => {
                            context.fs.appendFileSync(context.path.join(context.rootDir, 'log.txt'), 'task2\n')
                        },
                        (context: any) => {
                            context.fs.appendFileSync(context.path.join(context.rootDir, 'log.txt'), 'task3\n')
                        },
                    ],
                })

                await runScriptInProject({
                    scriptName: 'multiTask',
                    project,
                })

                // Verify all tasks executed in order
                const logPath = path.join('/', 'log.txt')
                expect(FileSystem.existsSync(fs, logPath)).toBe(true)
                expect(fs.readFileSync(logPath, { encoding: 'utf-8' })).toBe('task1\ntask2\ntask3\n')
            })

            test('handles non-function tasks with warning', async () => {
                vol.fromNestedJSON({
                    '/scripts': { 'mixed-tasks.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { mixedTasks: 'scripts/mixed-tasks.js' },
                    },
                })

                const scriptPath = project.resolvePath('scripts/mixed-tasks.js')
                registerMockScript(scriptPath, {
                    default: [
                        (context: any) => {
                            context.fs.writeFileSync(context.path.join(context.rootDir, 'valid.txt'), 'yes')
                        },
                        'not a function',
                        42,
                        null,
                    ],
                })

                await runScriptInProject({
                    scriptName: 'mixedTasks',
                    project,
                })

                // Only valid function executed
                expect(FileSystem.existsSync(fs, path.join('/', 'valid.txt'))).toBe(true)

                // Non-functions generated warnings
                expect(consoleWarnSpy).toHaveBeenCalledWith(expect.stringContaining('Skipping non-function task'))

                // Script completed
                expect(consoleInfoSpy).toHaveBeenCalledWith(expect.stringContaining('completed successfully'))
            })

            test('handles single non-function export gracefully', async () => {
                vol.fromNestedJSON({
                    '/scripts': { 'invalid.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { invalidExport: 'scripts/invalid.js' },
                    },
                })

                const scriptPath = project.resolvePath('scripts/invalid.js')
                registerMockScript(scriptPath, {
                    default: 'not a function',
                })

                await runScriptInProject({
                    scriptName: 'invalidExport',
                    project,
                })

                // Should warn
                expect(consoleWarnSpy).toHaveBeenCalledWith(expect.stringContaining('Skipping non-function task'))

                // Should complete
                expect(consoleInfoSpy).toHaveBeenCalledWith(expect.stringContaining('completed successfully'))
            })

            test('passes correct context with all required properties', async () => {
                vol.fromNestedJSON({
                    '/scripts': { 'context-check.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { contextTest: 'scripts/context-check.js' },
                    },
                })

                const scriptPath = project.resolvePath('scripts/context-check.js')
                registerMockScript(scriptPath, {
                    default: (context: any) => {
                        const result = {
                            hasRootDir: typeof context.rootDir === 'string',
                            hasConfig: typeof context.config === 'object',
                            hasFs: typeof context.fs === 'object',
                            hasPath: typeof context.path === 'object',
                            hasLogger: typeof context.logger === 'object',
                            hasRegisterExplicitId: typeof context.registerExplicitId === 'function',
                            scope: context.config.scope,
                        }
                        context.fs.writeFileSync(
                            context.path.join(context.rootDir, 'context.json'),
                            JSON.stringify(result)
                        )
                    },
                })

                await runScriptInProject({
                    scriptName: 'contextTest',
                    project,
                })

                // Verify context
                const resultPath = path.join('/', 'context.json')
                const result = JSON.parse(fs.readFileSync(resultPath, { encoding: 'utf-8' }) as string)

                expect(result).toEqual({
                    hasRootDir: true,
                    hasConfig: true,
                    hasFs: true,
                    hasPath: true,
                    hasLogger: true,
                    hasRegisterExplicitId: true,
                    scope: 'x_test',
                })
            })

            test('executes async tasks and waits for completion', async () => {
                vol.fromNestedJSON({
                    '/scripts': { 'async-test.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { asyncTest: 'scripts/async-test.js' },
                    },
                })

                const scriptPath = project.resolvePath('scripts/async-test.js')
                registerMockScript(scriptPath, {
                    default: async (context: any) => {
                        context.fs.writeFileSync(context.path.join(context.rootDir, 'start.txt'), 'started')

                        await new Promise((resolve) => setTimeout(resolve, 50))

                        context.fs.writeFileSync(context.path.join(context.rootDir, 'complete.txt'), 'done')
                    },
                })

                await runScriptInProject({
                    scriptName: 'asyncTest',
                    project,
                })

                // Both files should exist
                expect(FileSystem.existsSync(fs, path.join('/', 'start.txt'))).toBe(true)
                expect(FileSystem.existsSync(fs, path.join('/', 'complete.txt'))).toBe(true)
            })

            test('propagates errors from task functions', async () => {
                vol.fromNestedJSON({
                    '/scripts': { 'error-task.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { errorTask: 'scripts/error-task.js' },
                    },
                })

                const scriptPath = project.resolvePath('scripts/error-task.js')
                registerMockScript(scriptPath, {
                    default: () => {
                        throw new Error('Task execution failed')
                    },
                })

                await expect(
                    runScriptInProject({
                        scriptName: 'errorTask',
                        project,
                    })
                ).rejects.toThrow('Task execution failed')
            })

            test('prefers config script over fallback when both exist', async () => {
                vol.fromNestedJSON({
                    '/': { 'now.prebuild.mjs': '' },
                    '/scripts': { 'custom-prebuild.js': '' },
                })

                project = new Project({
                    rootDir: '/',
                    fileSystem: fs,
                    config: {
                        scope: 'x_test',
                        scopeId: '12345',
                        scripts: { prebuild: 'scripts/custom-prebuild.js' },
                    },
                })

                // Verify both files exist
                expect(projectHasScript(project, 'prebuild')).toBe(true)
                expect(FileSystem.existsSync(fs, '/now.prebuild.mjs')).toBe(true)
                expect(FileSystem.existsSync(fs, '/scripts/custom-prebuild.js')).toBe(true)

                // Mock the config script
                const configScriptPath = project.resolvePath('scripts/custom-prebuild.js')
                registerMockScript(configScriptPath, {
                    default: (context: any) => {
                        context.fs.writeFileSync(context.path.join(context.rootDir, 'config-script-ran.txt'), 'config')
                    },
                })

                // Mock the fallback script (should NOT be used)
                const fallbackScriptPath = project.resolvePath('now.prebuild.mjs')
                registerMockScript(fallbackScriptPath, {
                    default: (context: any) => {
                        context.fs.writeFileSync(
                            context.path.join(context.rootDir, 'fallback-script-ran.txt'),
                            'fallback'
                        )
                    },
                })

                await runScriptInProject({
                    scriptName: 'prebuild',
                    project,
                })

                // Config script should have run
                expect(FileSystem.existsSync(fs, '/config-script-ran.txt')).toBe(true)

                // Fallback script should NOT have run
                expect(FileSystem.existsSync(fs, '/fallback-script-ran.txt')).toBe(false)
            })
        })
    })
})
